// FUNCTION: BFME2 0x000408C0 size=9 name=?Rva000408C0NonzeroByte4@@YI_NPBE@Z evidence=?:placeholder tier=B hypothesis:cohesion

// FUNCTION: BFME2 0x000408D0 size=561 name=?Read@DebugIOCon@@UAEHPADH@Z evidence=N:ledger tier=B hypothesis:cohesion
int DebugIOCon::Read(char *buf, int maxchar)
{
	// We are not supporting reading from the console unless we allocated that console ourselves:
	// otherwise we would be snatching keyboard data away from the process that owns it.
	if (!m_allocatedConsole)
		return 0;

	// are we doing a continuous read?
	if (m_inputRead)
	{
		int numRead;
		if (maxchar > (int)(m_inputUsed - m_inputRead))
		{
			// return all
			numRead = m_inputUsed - m_inputRead;
			memcpy(buf, m_input + m_inputRead, numRead);
			m_inputRead = m_inputUsed = 0;
		}
		else
		{
			// return partially
			numRead = maxchar;
			memcpy(buf, m_input + m_inputRead, numRead);
			m_inputRead += maxchar;
		}
		return numRead;
	}

	// update our input buffer
	void *h = GetStdHandle(STD_INPUT_HANDLE);
	bool returnChars = false;
	for (;;)
	{
		unsigned long dwRecords;
		if (!GetNumberOfConsoleInputEvents(h, &dwRecords))
			break;
		if (!dwRecords)
			break;

		INPUT_RECORD record;
		ReadConsoleInputA(h, &record, 1, &dwRecords);
		if (record.EventType != KEY_EVENT)
			continue;

		KEY_EVENT_RECORD &key = record.Event.KeyEvent;
		if (!key.bKeyDown || !key.uChar.AsciiChar)
			continue;

		if (key.uChar.AsciiChar == '\r' || key.uChar.AsciiChar == '\n')
		{
			m_input[m_inputUsed++] = '\n';
			returnChars = true;
			break;
		}

		if (key.uChar.AsciiChar == '\b')
		{
			if (m_inputUsed)
				m_inputUsed--;
		}
		else if (((unsigned char)key.uChar.AsciiChar) >= ' ')
		{
			if (m_inputUsed < sizeof(m_input) - 1)
				m_input[m_inputUsed++] = key.uChar.AsciiChar;
		}
	}

	// update screen
	h = GetStdHandle(STD_OUTPUT_HANDLE);
	CONSOLE_SCREEN_BUFFER_INFO info;
	GetConsoleScreenBufferInfo(h, &info);
	CHAR_INFO ci[sizeof(m_input) + 1];
	for (unsigned k = 0; k <= sizeof(m_input); k++)
	{
		ci[k].Char.AsciiChar = k < m_inputUsed ? m_input[k] : ' ';
		ci[k].Attributes = BACKGROUND_GREEN | FOREGROUND_BLUE | FOREGROUND_GREEN | FOREGROUND_RED | FOREGROUND_INTENSITY;
	}

	// fake another cursor
	if (GetTickCount() & 512)
		ci[m_inputUsed].Attributes = BACKGROUND_BLUE | BACKGROUND_GREEN | BACKGROUND_RED | BACKGROUND_INTENSITY | FOREGROUND_GREEN;

	COORD srcSize, srcCoord;
	srcSize.X = sizeof(m_input);
	srcSize.Y = 1;
	srcCoord.X = srcCoord.Y = 0;

	SMALL_RECT r;
	r.Left = r.Top = r.Bottom = 0;
	r.Right = info.dwSize.X - 1;
	WriteConsoleOutputA(h, ci + ((int)m_inputUsed <= info.dwSize.X ? 0 : m_inputUsed - info.dwSize.X), srcSize, srcCoord, &r);

	// return data now?
	if (returnChars && m_inputUsed > 1)
	{
		*buf = *m_input;
		m_inputRead = 1;
		return 1;
	}

	return 0;
}


// FUNCTION: BFME2 0x00040B10 size=59 name=?bfmeWriteQN@@YGXHPAXPAD@Z evidence=N:ledger tier=B hypothesis:cohesion
void DebugIOCon::Write(StringType type, const char *src, const char *str)
{
	if (type == StructuredCmdReply || !str)
		return;

	unsigned long written;
	WriteFile(GetStdHandle(STD_OUTPUT_HANDLE), str, strlen(str), &written, NULL);
}

// FUNCTION: BFME2 0x00040B50 size=239 name=?Execute@DebugIOCon@@UAEXAAVDebug@@PBD_NIPBQBD@Z evidence=N:ledger tier=B hypothesis:cohesion
void DebugIOCon::Execute(Debug &dbg, const char *cmd, bool structuredCmd, unsigned int argn, const char *const *argv)
{
	if (!cmd || !strcmp(cmd, "help"))
	{
		dbg << "con I/O help:\n"
			   "  add [ <width> [ <height> ] ]\n"
			   "    create con I/O (optionally specifying the window size)\n";
	}
	else if (!strcmp(cmd, "add"))
	{
		if (argn > 0 && m_allocatedConsole)
		{
			// resize our console area
			void *h = GetStdHandle(STD_OUTPUT_HANDLE);
			COORD newSize;
			newSize.X = atoi(argv[0]);
			newSize.Y = argn > 1 ? atoi(argv[1]) : 25;
			SMALL_RECT sr;
			sr.Left = sr.Top = 0;
			sr.Right = newSize.X - 1;
			sr.Bottom = newSize.Y - 1;
			SetConsoleWindowInfo(h, 1, &sr);
			SetConsoleScreenBufferSize(h, newSize);
			SetConsoleWindowInfo(h, 1, &sr);
		}
	}
}


// FUNCTION: BFME2 0x00040C40 size=466 name=??0DebugIOCon@@QAE@XZ evidence=N:ledger tier=B hypothesis:K
DebugIOCon::DebugIOCon()
	: m_inputUsed(0), m_inputRead(0)
{
	// check: is there already a console window open?
	m_allocatedConsole = AllocConsole() != 0;
	if (m_allocatedConsole)
	{
		void *h = GetStdHandle(STD_INPUT_HANDLE);
		SetConsoleMode(h, 0);

		h = GetStdHandle(STD_OUTPUT_HANDLE);
		CONSOLE_SCREEN_BUFFER_INFO info;
		GetConsoleScreenBufferInfo(h, &info);

		// hide cursor
		CONSOLE_CURSOR_INFO ci;
		ci.dwSize = 1;
		ci.bVisible = 0;
		SetConsoleCursorInfo(h, &ci);

		SetConsoleCtrlHandler(bfmeIsBasic, 1);

		// find our console window by a unique title and remove its close button
		char oldTitle[100];
		GetConsoleTitleA(oldTitle, sizeof(oldTitle));
		char uniqueTitle[50];
		wsprintfA(uniqueTitle, "CON@%08x", this);
		SetConsoleTitleA(uniqueTitle);
		Sleep(40);
		void *wnd = FindWindowA(0, uniqueTitle);
		if (wnd)
		{
			void *menu = GetSystemMenu(wnd, 0);
			DeleteMenu(menu, SC_CLOSE, 0);
			DrawMenuBar(wnd);
		}
		SetConsoleTitleA(oldTitle);

		unsigned long written;
		WriteFile(GetStdHandle(STD_OUTPUT_HANDLE), "\n\nEA/Debug console open\n\n", 25, &written, 0);
	}

	// title the console after the executable
	char path[512];
	GetModuleFileNameA(0, path, sizeof(path));
	char *name = strrchr(path, '\\');
	name = name ? name + 1 : path;
	char title[512];
	strcpy(title, name);
	strcat(title, " [debug console]");
	SetConsoleTitleA(title);
}

